head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/yearanulfee_print.js");
//★Wcraft guide★ include부분 주석처리 -> include("../RexServer/rexscript/rexpert.js");
//★Wcraft guide★ include부분 주석처리 -> include("../RexServer/rexscript/rexpert_gauce.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF40800.xml";
scwin.BAS_YY = "";
scwin.COM_NM = "";
scwin.ANULFEE_EXMPT_YN = "";
scwin.LD_MKT_TP_CD = "";
scwin.PAY_TP_CD = "A";
scwin.params = new Array();
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.fn_SetMarket();
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.yafmgt.select.basyy";
    //"&{P}param01=" + LD_MKT_TP_CD;

    dts_BAS_YY.DataID = encodeURI(url);
    dts_BAS_YY.reset();
};
scwin.fn_SetMarket = function() {
    scwin.LD_MKT_TP_CD = js_market;
    if (scwin.LD_MKT_TP_CD == "9") {
        scwin.LD_MKT_TP_CD = mxr_mktGubun.getValue();
    }
};
scwin.fn_list_sync = function() {
    scwin.BAS_YY = cmb_BAS_YY.BindColVal;
    scwin.COM_NM = txb_COM_NM.getValue();
    scwin.ANULFEE_EXMPT_YN = cmb_ANULFEE_EXMPT_YN.BindColVal;
    scwin.PAY_TP_CD = cmb_PAY_TP_CD.BindColVal;
    scwin.fn_SetMarket();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=YEAR_ASSESSMENT_FEE_LIST_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.yafmgt.readYearAssessmentFeeNotiBas" + "&{P}param01=" + scwin.BAS_YY + "&{P}param02=" + scwin.LD_MKT_TP_CD;
    dts_ANULFEE_NOTI_BAS.DataID = encodeURI(url);
    dts_ANULFEE_NOTI_BAS.reset();
    if (scwin.ANULFEE_EXMPT_YN == "A") {
        scwin.ANULFEE_EXMPT_YN = "";
    }
    url = "/YearAssessmentFeeManagement.do?method=listYearAssessmentFee&inputMessageId=YEAR_ASSESSMENT_FEE_LIST_INOUT";
    url += "&BAS_YY=" + scwin.BAS_YY;
    url += "&COM_NM=" + scwin.COM_NM.replace("&", "＆");
    url += "&ANULFEE_EXMPT_YN=" + scwin.ANULFEE_EXMPT_YN;
    url += "&LD_MKT_TP_CD=" + scwin.LD_MKT_TP_CD;
    url += "&PAY_TP_CD=" + scwin.PAY_TP_CD;
    dts_yearAssessmentFee.DataID = encodeURI(url);
    dts_yearAssessmentFee.reset();
    var basYear = 2014;
    if (parseInt(scwin.BAS_YY) >= basYear) {
        $c.cm.setColumnProp(grd_main, 'CAP', 'show', false);
        $c.cm.setColumnProp(grd_main, 'AVG_MKTCAP', 'show', true);
    } else {
        $c.cm.setColumnProp(grd_main, 'CAP', 'show', true);
        $c.cm.setColumnProp(grd_main, 'AVG_MKTCAP', 'show', false);
    }
    if (scwin.LD_MKT_TP_CD == "1") {
        //	유가
        $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', false);
        $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', false);
    } else {
        //	코스닥(면제금액,실납부금액)
        $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', true);
        $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', true);
    }
    $c.cm.ShowWin(grd_main);
};
scwin.fn_update = function() {
    if (txb_ANULFEE_FINAL_YN.getValue() != "N") {
        //과거자료때문에..'N으로 check
        $c.win.alert("이미 [연부과금 확인] 처리가 되었습니다.");
        return;
    }
    if (scwin.fn_printCheck() != true) {
        return;
    }
    var rtn = confirm('[연부과금 확인]을 선택시에는 상장법인이 제출시스템에서 연부과금을 확인을 할수가 있어 수정이 불가능합니다. \n[연부과금 확인]을 처리 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_yearAssessmentFee.UserStatus(1) = 1;*/
        X = 1;
        var url = "/YearAssessmentFeeManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=updateAnulfeeFinalYn";
        url += "&BAS_YY=" + scwin.BAS_YY;
        url += "&LD_MKT_TP_CD=" + scwin.LD_MKT_TP_CD;
        url += "&ANULFEE_ENFORCE_DD=" + edt_ANULFEE_ENFORCE_DD.getValue(); //시행일자
        url += "&PAY_DEADLINE_DD=" + edt_PAY_DEADLINE_DD.getValue(); //납부기한
        url += "&ANULFEE_PAY_METHD_DSC=" + txb_ANULFEE_PAY_METHD_DSC.getValue(); //납부방법
        url += "&EMP_NO=" + js_emp_no; //확인사원번호
        trs_Update.Action = encodeURI(url);
        trs_Update.KeyValue = "JSP(I:pInput=dts_yearAssessmentFee)";
        trs_Update.Post();
    }
};
scwin.fn_printCheck = function() {
    if (edt_ANULFEE_ENFORCE_DD.getValue() == "") {
        $c.win.alert("[시행일]을 입력하세요.");
        edt_ANULFEE_ENFORCE_DD.focus();
        return false;
    }
    if (edt_PAY_DEADLINE_DD.getValue() == "") {
        $c.win.alert("[납부기한]을 입력하세요.");
        edt_PAY_DEADLINE_DD.focus();
        return false;
    }
    if (edt_ANULFEE_ENFORCE_DD.getValue() > edt_PAY_DEADLINE_DD.getValue()) {
        $c.win.alert("시행일은 납부기한보다 클수없습니다. 다시 선택해주세요.");
        edt_ANULFEE_ENFORCE_DD.focus();
        return false;
    }
    if (txb_ANULFEE_PAY_METHD_DSC.getValue() == "") {
        $c.win.alert("납부방법을 입력하세요.");
        txb_ANULFEE_PAY_METHD_DSC.focus();
        return false;
    }
    return true;
};
scwin.fn_setId = function(obj) {
    scwin.params[0] = dts_yearAssessmentFee.getCellData(eval(obj), "ISUR_CD");
    scwin.params[1] = dts_yearAssessmentFee.getCellData(eval(obj), "BAS_YY");
    scwin.params[2] = dts_yearAssessmentFee.getCellData(eval(obj), "LD_MKT_TP_CD");
    scwin.params[3] = dts_yearAssessmentFee.getCellData(eval(obj), "ANULFEE_NOTI_IMPOST_NO");
};
scwin.fn_getId = function() {
    return scwin.params;
};


/**
 *  연부과금 생성
 * fn_HoldyYn
 */
scwin.fn_calcul = function() {
    var gYYYY = $c.ut.cGetToday("yyyymmdd").substring(0, 4);
    var rtn = confirm(gYYYY + '년(부과년도기준) 연부과금을 생성 하시겠습니까?');
    if (rtn == 1) {
        scwin.fn_SetMarket();
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=LISTING_COUNT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.yafmgt.select.anulfee.create" + "&{P}param01=" + scwin.LD_MKT_TP_CD;
        dts_CalCul.DataID = encodeURI(url);
        dts_CalCul.reset();
        var gCnt = -1;
        dts_CalCul.insertRow();
        gCnt = dts_CalCul.getCellData(1, "CNT");
        if (gCnt > 0) {
            $c.win.alert("이미 생성되었습니다.");
        } else {
            var url = "/YearAssessmentFeeManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=createAnulfee";
            url += "&LD_MKT_TP_CD=" + scwin.LD_MKT_TP_CD;
            trs_CalCul.Action = encodeURI(url);
            //trs_CalCul.KeyName     = "toinb_dataid4";
            trs_CalCul.KeyValue = "JSP(I:pInput=dts_CalCul)";
            trs_CalCul.Post();
        }
    }
};
scwin.trs_CalCul_OnFail = function() {
    //alert(getMessageParam("MSG-0002", ""));
    $c.win.alert($c.stf.getMessageParam("MSG-0002", "") + "\n" + trs_CalCul.ErrorMsg);
};
scwin.trs_CalCul_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
    scwin.fn_SetCode();
    scwin.fn_list_sync();
};
scwin.trs_Update_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
    scwin.fn_list_sync();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert(trs_Update.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.btn_confirm_onclick = function() {
    scwin.fn_update();
};
scwin.btn_print_onclick = function() {
    grd_main.redraw = false;
    for (i = 1; i <= dts_yearAssessmentFee.getTotalRow(); i++) {
        dts_yearAssessmentFee.setCellData(i, "ANULFEE_ENFORCE_DD", edt_ANULFEE_ENFORCE_DD.getValue());
        dts_yearAssessmentFee.setCellData(i, "PAY_DEADLINE_DD", edt_PAY_DEADLINE_DD.getValue());
        dts_yearAssessmentFee.setCellData(i, "ANULFEE_PAY_METHD_DSC", txb_ANULFEE_PAY_METHD_DSC.getValue());
    }
    grd_main.Redraw = true;

    //	if (dts_yearAssessmentFee.NameString(1,"ANULFEE_FINAL_YN") != "Y") {
    //		alert("연부과금 확인을 하셔야 인쇄를 하실수있습니다.");
    //		return ;
    //	}

    if (dts_yearAssessmentFee.getCellData(1, "LD_MKT_TP_CD") == "1") {
        if (parseInt(scwin.BAS_YY) >= 2014) {
            $c.yp.fn_pre_print_stock(dts_yearAssessmentFee, chk_test.checked, '1');
        } else {
            $c.yp.fn_pre_print_stock(dts_yearAssessmentFee, chk_test.checked, '2');
        }
    } else {
        if (parseInt(scwin.BAS_YY) >= 2014) {
            $c.yp.fn_pre_print_kosdaq(dts_yearAssessmentFee, chk_test.checked, '1');
        } else {
            $c.yp.fn_pre_print_kosdaq(dts_yearAssessmentFee, chk_test.checked, '2');
        }
    }
};
scwin.btn_print_old_onclick = function() {
    grd_main.redraw = false;
    for (i = 1; i <= dts_yearAssessmentFee.getTotalRow(); i++) {
        dts_yearAssessmentFee.setCellData(i, "ANULFEE_ENFORCE_DD", edt_ANULFEE_ENFORCE_DD.getValue());
        dts_yearAssessmentFee.setCellData(i, "PAY_DEADLINE_DD", edt_PAY_DEADLINE_DD.getValue());
        dts_yearAssessmentFee.setCellData(i, "ANULFEE_PAY_METHD_DSC", txb_ANULFEE_PAY_METHD_DSC.getValue());
    }
    grd_main.Redraw = true;

    //	if (dts_yearAssessmentFee.NameString(1,"ANULFEE_FINAL_YN") != "Y") {
    //		alert("연부과금 확인을 하셔야 인쇄를 하실수있습니다.");
    //		return ;
    //	}

    if (dts_yearAssessmentFee.getCellData(1, "LD_MKT_TP_CD") == "1") {
        if (parseInt(scwin.BAS_YY) >= 2014) {
            $c.yp.fn_pre_print_stock_old(dts_yearAssessmentFee, chk_test.checked, '1');
        } else {
            $c.yp.fn_pre_print_stock_old(dts_yearAssessmentFee, chk_test.checked, '2');
        }
    } else {
        if (parseInt(scwin.BAS_YY) >= 2014) {
            $c.yp.fn_pre_print_kosdaq_old(dts_yearAssessmentFee, chk_test.checked, '1');
        } else {
            $c.yp.fn_pre_print_kosdaq_old(dts_yearAssessmentFee, chk_test.checked, '2');
        }
    }
};
scwin.grd_main_OnDblClick = async function(row, colid) {
    scwin.fn_setId(row);
    if ( /*dts_yearAssessmentFee.NameString(row, "LD_MKT_TP_CD")  == '2' &&*/ dts_yearAssessmentFee.getCellData(row, "ANULFEE_PAY_TP_CD") == "U") {
        await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF40802.gfm", "수시 연부과금 관리", 200, 100, 525, 365, "window");
    } else {
        await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF40801.gfm", "연부과금 수정", 200, 100, 525, 500, "window");
    }
    scwin.fn_list_sync();
};
scwin.btn_toexcel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_main, "연부과금내역", "", "8");
};
scwin.dts_yearAssessmentFee_OnLoadCompleted = function(rowcount) {
    if (dts_yearAssessmentFee.ErrorMsg) {
        $c.win.alert(dts_yearAssessmentFee.ErrorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_yearAssessmentFee.removeAll();
        }
        $c.cm.CloseWin(rowcount, grd_main); //데이터 로딩중닫기 및 조회없음 처리

        var basYear = 2014;
        if (parseInt(scwin.BAS_YY) >= basYear) {
            //시가총액합계
            txb_cap_tot.setValue($c.stf.FormatNumberEx(dts_yearAssessmentFee.Sum(33, 1, rowcount), 3));
            $c.stf.showObj(lbl_CAP, false);
            $c.stf.showObj(lbl_AVG_MKTCAP, true);
        } else {
            //자본금합계
            txb_cap_tot.setValue($c.stf.FormatNumberEx(dts_yearAssessmentFee.Sum(10, 1, rowcount), 3));
            $c.stf.showObj(lbl_CAP, true);
            $c.stf.showObj(lbl_AVG_MKTCAP, false);
        }
        var url = "/YearAssessmentFeeManagement.do?method=listYearAssessmentFeeSum&inputMessageId=YEAR_ASSESSMENT_FEE_SUM_INOUT";
        url += "&BAS_YY=" + scwin.BAS_YY;
        url += "&COM_NM=" + scwin.COM_NM;
        url += "&ANULFEE_EXMPT_YN=" + scwin.ANULFEE_EXMPT_YN;
        url += "&LD_MKT_TP_CD=" + scwin.LD_MKT_TP_CD;
        dts_yearAssessmentFeeTot.DataID = encodeURI(url);
        dts_yearAssessmentFeeTot.reset();
    }
};
scwin.dts_yearAssessmentFeeTot_OnLoadCompleted = function(rowcount) {
    dts_yearAssessmentFeeTot.insertRow();
    dts_yearAssessmentFeeTot.setCellData(dts_yearAssessmentFeeTot.getRowPosition(), "GUBUN", "합계");
    dts_yearAssessmentFeeTot.setCellData(dts_yearAssessmentFeeTot.getRowPosition(), "ANULFEE_TOTAL1", dts_yearAssessmentFeeTot.Sum(2, 1, 6));
    dts_yearAssessmentFeeTot.setCellData(dts_yearAssessmentFeeTot.getRowPosition(), "ANULFEE_TOTAL2", dts_yearAssessmentFeeTot.Sum(3, 1, 6));
    dts_yearAssessmentFeeTot.setCellData(dts_yearAssessmentFeeTot.getRowPosition(), "ANULFEE_TOTAL", dts_yearAssessmentFeeTot.Sum(4, 1, 6));
};
scwin.dts_yearAssessmentFee_OnLoadError = function() {
    $c.stf.alert_error(dts_yearAssessmentFee);
};
scwin.dts_yearAssessmentFeeTot_OnLoadError = function() {
    $c.stf.alert_error(dts_yearAssessmentFeeTot);
};
scwin.dts_ANULFEE_NOTI_BAS_OnLoadError = function() {
    $c.stf.alert_error(dts_ANULFEE_NOTI_BAS);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_calcul_onclick = function() {
    scwin.fn_calcul();
};
scwin.btn_close_onclick = function() {
    self.close();
};
scwin.img_ANULFEE_ENFORCE_DD_onclick = function() {
    popUpCalendar2(edt_ANULFEE_ENFORCE_DD);
};
scwin.img_PAY_DEADLINE_DD_onclick = function() {
    popUpCalendar2(edt_PAY_DEADLINE_DD);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    $c.stf.showObj(btn_print_old, false); //rexpert

    //(3393)유가도 환율정보 입력 가능 2011.03 - label_12
    if (js_market == "1" || js_market == "2") {
        $c.stf.showObj(panel_mkt_gubun_1, false);
        $c.stf.showObj(panel_mkt_gubun_2, false);
        $c.stf.showObj(label_12, true);
        if (js_market == "1") {
            var strANULFEE_EXMPT_YN = "A^전체,Y^Y,N^N";
            cmb_ANULFEE_EXMPT_YN.CBData = strANULFEE_EXMPT_YN;
            cmb_ANULFEE_EXMPT_YN.setSelectedIndex(0);
            $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', false);
            $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', false);
        } else {
            var strANULFEE_EXMPT_YN = "A^전체,Y^Y,E^Y(일부면제),N^N";
            cmb_ANULFEE_EXMPT_YN.CBData = strANULFEE_EXMPT_YN;
            cmb_ANULFEE_EXMPT_YN.setSelectedIndex(0);
            $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', true);
            $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', true);
        }
    } else {
        $c.stf.showObj(panel_mkt_gubun_1, true);
        $c.stf.showObj(panel_mkt_gubun_2, true);
        $c.stf.showObj(label_12, true);
        var strANULFEE_EXMPT_YN = "A^전체,Y^Y,E^Y(일부면제),N^N";
        cmb_ANULFEE_EXMPT_YN.CBData = strANULFEE_EXMPT_YN;
        cmb_ANULFEE_EXMPT_YN.setSelectedIndex(0);
        $c.cm.setColumnProp(grd_main, 'ANULFEE_EXMPT_AMT', 'show', false);
        $c.cm.setColumnProp(grd_main, 'ANULFEE_REAL_PAY_AMT', 'show', false);
    }
    scwin.fn_SetCode();
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);

    /*if(js_market == "2"  ){*/
    var basYear = 2014;
    if (parseInt(scwin.BAS_YY) >= basYear) {
        $c.stf.showObj(label_basYY1, false);
        $c.stf.showObj(label_basYY2, true);
        /*showObj(pan_KOSDAQ, true);*/
        //showObj(pan_PAY_TP_CD, true);
        $c.stf.showObj(pan_NewUnSchedule, true);
    } else {
        $c.stf.showObj(label_basYY1, true);
        $c.stf.showObj(label_basYY2, false);
        /*showObj(pan_KOSDAQ, false);*/
        //showObj(pan_PAY_TP_CD, false);
        $c.stf.showObj(pan_NewUnSchedule, false);
    }
    $c.stf.showObj(lbl_anualFeeInfo1, true);
    $c.stf.showObj(lbl_anualFeeInfo2, true);
    /*}*/

};
scwin.btn_modiPrintContent_onclick = function() {
    /*시행일자, 납부기한, 납부방법을 변경할 수 있도록 요청 */

    if (txb_ANULFEE_FINAL_YN.getValue() != "N") {
        //과거자료때문에..'N으로 check
        $c.win.alert("이미 [연부과금 확인] 처리가 되었습니다.");
        return;
    }
    if (scwin.fn_printCheck() != true) {
        return;

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

    } /*ORG SRC: dts_ANULFEE_NOTI_BAS.UserStatus(1) = 1;*/ X = 1;
    var url = "/YearAssessmentFeeManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=updateAnulfeePrintContent";
    url += "&BAS_YY=" + scwin.BAS_YY;
    url += "&LD_MKT_TP_CD=" + scwin.LD_MKT_TP_CD;
    url += "&ANULFEE_ENFORCE_DD=" + edt_ANULFEE_ENFORCE_DD.getValue(); //시행일자
    url += "&PAY_DEADLINE_DD=" + edt_PAY_DEADLINE_DD.getValue(); //납부기한
    url += "&ANULFEE_PAY_METHD_DSC=" + txb_ANULFEE_PAY_METHD_DSC.getValue(); //납부방법
    url += "&EMP_NO=" + js_emp_no; //확인사원번호
    trs_Update.Action = encodeURI(url);
    trs_Update.KeyValue = "JSP(I:pInput=dts_ANULFEE_NOTI_BAS)";
    trs_Update.Post();
};
